    public List<PricingPlan> testGetAll() throws Throwable {
    LOGGER.info( "PricingPlanTest:testGetAll() - Retrieving Collection of PricingPlans:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all PricingPlan : " );
    List<PricingPlan> collection  = null;

    try {
        // call the static get method on the PricingPlanService
        collection = service.getAllPricingPlan();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            PricingPlan currEntity  = null;
            Iterator<PricingPlan> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPricingPlanId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

